class FlagTranslator(object):

    def __init__(self, arch):
        self.__arch = arch
        self.__flags = {}

    def __getattr__(self, flag):
        return self.__get_flag(flag)

    def __getitem__(self, flag):
        return self.__get_flag(flag)

